namespace LookAndFeel
{
    const var knob = Content.createLocalLookAndFeel();
    knob.registerFunction("drawRotarySlider", function(g, obj) { ... });

    const var button = Content.createLocalLookAndFeel();
    button.registerFunction("drawToggleButton", function(g, obj) { ... });
