name: addComponentRefreshListener
params:
  - { name: componentIds, type: var, desc: "Component reference(s) -- a single component (name string or reference) or an array" }
  - { name: refreshType, type: String, desc: "The refresh action to perform when the broadcaster fires" }
  - { name: metadata, type: var, desc: "Listener metadata -- a string ID or JSON object with at least an `id` field" }
---
::

```javascript
bc.addComponentRefreshListener("Panel1", "repaint", "refresher");
```


Adds a target that triggers a refresh action on the specified UI components whenever the broadcaster fires, ignoring the broadcast arguments entirely. The `refreshType` string determines the action:

| Refresh Type | Action |
|---|---|
| `"repaint"` | Triggers the component's paint routine or LAF function |
| `"changed"` | Triggers the control callback as if the user interacted with it |
| `"updateValueFromProcessorConnection"` | Refreshes the displayed value from the connected processor parameter |
| `"loseFocus"` | Removes keyboard/mouse focus |
| `"resetValueToDefault"` | Resets the value to the component's default |

#### Example

```javascript
const var button = Content.addButton("Button1", 0, 0);

const var PanelArray = [Content.addPanel("Panel4", 0, 50),
                        Content.addPanel("Panel3", 100, 50),
                        Content.addPanel("Panel2", 200, 50),
                        Content.addPanel("Panel1", 300, 50)];

for(p in PanelArray)
{
	p.setPaintRoutine(function(g)
	{
		g.setColour(Colours.withAlpha(Colours.white, Math.random()));
		g.fillRect(this.getLocalBounds(0));

	});
}

const var bc = Engine.createBroadcaster({
	"id": "RepaintBroadcaster",
	"colour": -1,
	"args": ["index"]
});


bc.addComponentRefreshListener(PanelArray, "repaint", "Repaint Panels");

inline function onButton(component, value)
{
	// just send out any value to trigger the broadcaster
	bc.index = Math.random(); 
}

button.setControlCallback(onButton);
```

