name: addComponentValueListener
params:
  - { name: object, type: var, desc: "Component reference(s) -- a single component (name string or reference) or an array of components" }
  - { name: metadata, type: var, desc: "Listener metadata -- a string ID or JSON object with at least an `id` field" }
