    "args": ["processorId", "parameterId", "value"]
});

bc.addModuleParameterSyncer("SyncGain", "Gain", "gainTarget");
bc.sendSyncMessage(["SyncGain", "Gain", -12.0]);

const var gain = Synth.getEffect("SyncGain");
