---
name: attachToContextMenu
params:
  - { name: componentIds, type: var, desc: "Component reference(s) -- a single component (name string or reference) or an array of components" }
  - { name: stateFunction, type: var, desc: "State callback for menu item appearance, or `false` to disable state management" }
  - { name: itemList, type: var, desc: "Menu item labels -- a single string or an array of strings" }
  - { name: optionalMetadata, type: var, desc: "Optional source metadata -- a string ID or JSON object" }
  - { name: useLeftClick, type: var, desc: "If `true`, the context menu opens on left-click instead of right-click" }
---
::

```javascript
bc.attachToContextMenu("Panel1", false, ["Item A", "Item B"], "menuSource", false);
```


Registers a popup context menu on the specified components. When the user right-clicks (or double-taps on trackpad, or Ctrl+clicks on macOS), a popup menu appears using the component's LookAndFeel customisation. When the user selects an item, the broadcaster fires with `(componentReference, selectedItemIndex)` where the index is zero-based. Set `useLeftClick` to `true` to open the menu on left-click instead.

The `itemList` supports pseudo-markdown formatting: `**Bold Text**` for section headers, `___` for horizontal separators, and `~~Strikethrough~~` for always-disabled items. Use the `{DYNAMIC}` wildcard in an item's text to request dynamic text from the state function at display time.

The optional `stateFunction` controls menu item appearance. It receives `(type, index)` where `this` points to the clicked component, and must return a value:

| Type | Return | Purpose |
|---|---|---|
| `"active"` | Boolean | Whether the item shows a tick mark |
| `"enabled"` | Boolean | Whether the item is interactable (not greyed out) |
| `"text"` | String | Dynamic text override (empty string uses the static label) |

Pass `false` for the state function to skip state management.

::warning{title="State function results are cached"}
State function results are cached and only refreshed after a menu selection or an explicit `refreshContextMenuState()` call. If external state changes between menu openings, call `refreshContextMenuState()` to update tick marks and enabled states.
::

::warning{title="Does not override right-click behaviour"}
This attachment does not override existing right-click behaviour. Disable `enableMidiLearn` on attached components to prevent the MIDI learn popup from conflicting with the context menu.
::

#### Example

```javascript
// We'll attach the context menu to this button
const var Button1 = Content.addButton("Button1", 0, 0);
Button1.set("enableMidiLearn", false); // we don't want this to popup too...

/** Let's define a broadcaster with two arguments. */
const var bc = Engine.createBroadcaster({
	"id": "ContextMenu Broadcaster",
	"args": ["component", "selectedIndex"]
});

/** This defines a few items using a markdown-like syntax. */
const var POPUP_MENU_ITEMS = [
  "**Set Value / Properties**", // A header
  "Value is active",			// the first item
  "Set to {DYNAMIC}",			// the second item with a dynamic text
  "___",						// a horizontal separator
  "~~This is always off~~"		// an item that is always disabled
];


inline function popupStateFunction(type, index)
{
	// The this object of this function will always
	// point to the component that was clicked (in our
	// case it's always Button1).
	Console.assertEqual(this, Button1);

	local getEnableState = type == "enabled";
	local getTextValue = type == "text";
	local getActiveState = type == "active";

	if(getEnableState) // We don't want to disable any item
		return true; // so let's return true...

	if(getTextValue)
	{
		// This function is only called with items
		// that specify the `{DYNAMIC}` wildcard
		// in this case the second item with the index 1
		Console.assertEqual(value, 1);

		// Now we can return whatever text we want to show
		// and this is evaluated each time before the popup
		// is shown
		return this.get("width") > 150 ? "small" : "wide";
	}

	if(getActiveState)
	{
		// Now we can decide whether the popup menu item
		// should be displayed as active or not

		// the first item checks whether the button is active
		if(index == 0)
			return this.getValue();

		// the second item checks whether its wide or not
		if(index == 1)
			return this.get("width") > 150;
	}
};

/** Now we can use the item list and the state function to attach the broadcaster
   to the context menu of the button (you can attach it to multiple components by
   passing in a list. */
bc.attachToContextMenu("Button1", popupStateFunction, POPUP_MENU_ITEMS, "Context Menu");


/** This callback will be executed whenever a popup menu item was selected. */
bc.addListener(Button1, "Menu callback", function(component, index)
{
	// the this object will point to the component
	Console.assertEqual(component, this);

	if(index == 0)
	{
		this.setValue(!component.getValue());
		this.changed();
	}
	if(index == 1)
	{
		this.set("width", component.get("width") > 150 ? 100 : 200);
	}
});
```

