name: attachToRadioGroup
params:
  - { name: radioGroupIndex, type: int, desc: "The radio group index to monitor" }
  - { name: optionalMetadata, type: var, desc: "Source metadata -- a string ID or JSON object" }
---
::

```javascript
bc.attachToRadioGroup(1, "radioSource");
```


Attaches the broadcaster to a radio button group, firing whenever a button in the group is clicked. The broadcaster receives the zero-based index of the selected button within the group (using the same order as the component list). On attachment, existing listeners immediately receive the index of the currently active button.

This is the only attachment mode that supports bidirectional communication: sending a message via dot-assignment (`bc.buttonIndex = 2`) or `sendSyncMessage` also changes the currently active button in the radio group.

This is commonly used for page-handling logic: attach to a radio group, then use `addComponentPropertyListener` to show or hide page panels based on the selected index.

::warning{title="RadioGroupIndex must be greater than zero"}
The `radioGroupIndex` must be a positive integer (greater than zero). Passing `0` produces an error.
::

#### Example

```javascript
const var bc = Engine.createBroadcaster({
	"id": "My Page Handler",
	"colour": -1,
	"comment": "This broadcaster will handle the page logic",
	"args": ["pageIndex"]
});

// Just a dummy function that 
inline function addRadioButton(i)
{
	local b = Content.addButton("RadioButton " + (i+1), 0, i * 30);
	b.set("radioGroup", 90);
	b.set("saveInPreset", false);

	local p = Content.addPanel("Page" + (i+1), 150 + i* 100, 0);
	p.set("visible", false);
	return p;
}

// This array will hold 4 panels
const var Pages = [];

// Create 4 radio buttons and 4 panels
for(i = 0; i < 4; i++)
	Pages.push(addRadioButton(i));

bc.attachToRadioGroup(90, "Button Group");

const var PageList = []; //

bc.addComponentPropertyListener(Pages, "visible", "Show Panels", function(indexInList, buttonIndex)
{
	return indexInList == buttonIndex;
});

// Show the first page
bc.pageIndex = 0;
```

