const var bc = Engine.createBroadcaster({
    "id": "DebounceBC",
    "args": ["value"]
});

var lastReceived = -1;

inline function onDebounced(value)
{
    lastReceived = value;
}

bc.addDelayedListener(100, "handler", "debounce", onDebounced);
bc.sendSyncMessage([1]);
bc.sendSyncMessage([2]);
bc.sendSyncMessage([3]);
```

