name: withMultipliedSaturation
params:
  - { name: colour, type: Colour, desc: "The base colour" }
  - { name: factor, type: double, desc: "Multiplier for the current saturation value" }
---
::

```javascript
var muted = Colours.withMultipliedSaturation(Colours.red, 0.5);
```


Scales the existing saturation (HSB saturation component) by the given factor rather than replacing it. A factor of 0.0 produces greyscale, 1.0 leaves the colour unchanged, and values above 1.0 increase saturation (clamped internally). Hue, brightness, and alpha are preserved. A common pattern is to tie the factor to a normalised parameter value, creating a visual link between a knob's position and the colour intensity of its arc.

#### Value Saturation

```javascript
// Context: Desaturating a knob's colour when its value is low and
// fully saturating it at maximum. This creates a visual link between
// the parameter value and the colour intensity. The factor is the
// normalized knob value (0.0-1.0), clamped to a minimum so the
// colour never goes fully grey.

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
    // Clamp to 0.2 minimum so the arc is always slightly coloured
    var c = Colours.withMultipliedSaturation(obj.itemColour1, Math.max(0.2, obj.valueNormalized));
    g.setColour(c);
    g.drawEllipse(Rect.reduced(obj.area, 4.0), 2.0);
});
```

