name: writeAudioFile
params:
  - { name: audioData, type: var, desc: "Audio sample data in one of the four accepted shapes" }
  - { name: sampleRate, type: double, desc: "Output sample rate in Hz" }
  - { name: bitDepth, type: int, desc: "Bits per sample for the output file" }
---
::

```javascript
var ok = f.writeAudioFile(buffer, 44100.0, 24);
```


Writes audio data to this file. The output format is determined by the file extension: `.wav` for WAV, `.aiff` for AIFF, `.flac` for FLAC, `.ogg` for OGG. The `audioData` parameter accepts several input shapes: a single Buffer (mono), an Array of Buffers (multi-channel), an Array of number arrays, or a plain number array (mono). For multi-channel data, all channels must have the same sample count.

::warning{title="Deletes existing file before write"}
The existing file is deleted before the write begins. If the write fails, the original file is lost. Use `getNonExistentSibling()` when exporting to avoid overwriting user files.
::

::warning{title="Only WAV, AIFF, and FLAC supported"}
HLAC format is supported for reading (via `loadAsAudioFile`) but not for writing. Using an unrecognised extension like `.mp3` or `.hlac` triggers a script error.
::

#### Export Stereo Unique Name

```javascript
// Context: Exporting rendered audio without overwriting existing files

const var exportDir = FileSystem.getFolder(FileSystem.Desktop);

inline function exportAudio(bufferData, fileName)
{
    local targetFile = exportDir.getChildFile(fileName);

    // Avoid overwriting - get a unique sibling name like "mix (2).wav"
    targetFile = targetFile.getNonExistentSibling();

    // Trim trailing silence before writing
    local channelsToWrite = [
        bufferData[0].trim(0, 0),
        bufferData[1].trim(0, 0)
    ];

    targetFile.writeAudioFile(channelsToWrite, Engine.getSampleRate(), 24);
    Console.print("Exported: " + targetFile.toString(0));

    return targetFile;
}

// Usage: export a stereo sine wave
const var left = Buffer.create(44100);
const var right = Buffer.create(44100);

for (i = 0; i < 44100; i++)
{
    left[i] = Math.sin(2.0 * Math.PI * 440.0 * i / 44100.0);
    right[i] = left[i];
}

exportAudio([left, right], "mix.wav");
```

