name: writeMidiFile
params:
  - { name: eventList, type: var, desc: "Array of MessageHolder objects representing MIDI events" }
  - { name: metadataObject, type: var, desc: "JSON object with time signature and tempo metadata" }
---
::

```javascript
var ok = f.writeMidiFile(events, {"Tempo": 120.0, "Nominator": 4, "Denominator": 4});
```


Writes an array of MessageHolder objects as a standard MIDI file. The optional metadata object accepts the same time signature properties as `loadMidiMetadata` returns - see `loadMidiMetadata` for the object format. If `NumBars` is omitted or zero, it is auto-calculated from the last event's timestamp. Non-MessageHolder elements in the array are silently skipped. Returns `true` on success.

#### Export Midi Unique Name

```javascript
// Context: Exporting sequencer pattern data as a standard MIDI file

const var tempDir = FileSystem.getFolder(FileSystem.Temp);

inline function exportMidiPattern(eventList, metadata)
{
    // Generate a unique filename to avoid overwriting
    local targetFile = tempDir.getChildFile("Pattern.mid").getNonExistentSibling();

    // Clean up any stale file at this path
    targetFile.deleteFileOrDirectory();

    local ok = targetFile.writeMidiFile(eventList, metadata);

    if (ok)
        Console.print("MIDI exported: " + targetFile.toString(3));

    return targetFile;
}

// Create a single-note event and export
var events = [];
var noteOn = Engine.createMessageHolder();
noteOn.setType(noteOn.NoteOn);
noteOn.setNoteNumber(60);
noteOn.setVelocity(100);
noteOn.setTimestamp(0);
events.push(noteOn);

exportMidiPattern(events, {"Tempo": 120.0, "NumBars": 1});
```

