name: fromAbsolutePath
params:
  - { name: path, type: String, desc: "Absolute filesystem path to create a File object for." }
---
::

```javascript
var f = FileSystem.fromAbsolutePath("C:/Users/MyFile.txt");
```


Creates a `File` object from an absolute filesystem path string. The path must be absolute (e.g. `C:/Users/MyFile.txt` on Windows or `/Users/name/file.txt` on macOS). The method does not verify that the file exists on disk - it only validates the path format. Use `File.isFile()` or `File.isDirectory()` on the returned object to check existence. This is particularly useful for converting path strings from `ScriptPanel.setFileDropCallback()` into `File` objects, or for reconstructing files from stored path strings.

::warning{title="Relative paths return undefined"}
Returns `undefined` silently when given a relative path or non-path string. Check with `isDefined()` if the path source is untrusted.
::

#### Reconstruct File From Stored Path (skipped)

```javascript
// Context: When saving file paths to JSON (for caches, recent files, or
// favorites), you store the absolute path as a string. To work with
// the file again, reconstruct the File object with fromAbsolutePath().

// Saving a path for later
var recentFiles = [];

inline function addToRecentFiles(file)
{
    local path = file.toString(0); // Full absolute path as string
    recentFiles.push(path);

    // Persist to AppData
    FileSystem.getFolder(FileSystem.AppData)
              .getChildFile("recentFiles.json")
              .writeObject(recentFiles);
}

// Restoring files from stored paths
inline function loadRecentFiles()
{
    local stored = FileSystem.getFolder(FileSystem.AppData)
                             .getChildFile("recentFiles.json")
                             .loadAsObject();

    if (!isDefined(stored))
        return [];

    local validFiles = [];

    for (path in stored)
    {
        local f = FileSystem.fromAbsolutePath(path);

        // Verify the file still exists before adding
        if (isDefined(f) && f.isFile())
            validFiles.push(f);
    }

    return validFiles;
}
```

