name: fromReferenceString
params:
  - { name: referenceStringOrFullPath, type: String, desc: "A HISE reference string with `{PROJECT_FOLDER}` wildcard, or an absolute file path." }
  - { name: locationType, type: int, desc: "A `SpecialLocations` constant identifying which resource pool to resolve against." }
---
::

```javascript
var f = FileSystem.fromReferenceString("{PROJECT_FOLDER}impulse.wav", FileSystem.AudioFiles);
```


Resolves a HISE resource reference string (e.g. `{PROJECT_FOLDER}impulse.wav`) or an absolute file path into a `File` object. The `locationType` parameter determines which resource pool to resolve against and must be one of three constants:

| Location Type | Pool |
|---------------|------|
| `FileSystem.AudioFiles` | Non-streaming audio files (impulse responses, loops) |
| `FileSystem.Samples` | Streaming sample files |
| `FileSystem.UserPresets` | User preset files |

This is useful for converting the reference strings returned by `AudioSampleProcessor.getFilename()` back into `File` objects for display or navigation.

::warning{title="Returns undefined for embedded resources"}
Returns `undefined` for embedded resources in exported plugins. Code that works in the HISE IDE - where files exist on disk - will fail silently in compiled plugins if the resource has been embedded into the binary. Check with `isDefined()`.
::

#### Resolve Audio Reference For Display (skipped)

```javascript
// Context: AudioSampleProcessor.getFilename() returns a HISE reference string
// like "{PROJECT_FOLDER}sound.wav". To show the filename in the UI or navigate
// to the parent directory, resolve it to a File object first.

const var player = Synth.getAudioSampleProcessor("AudioPlayer1");

inline function getCurrentAudioFile()
{
    local refString = player.getFilename();

    if (!refString.length)
        return undefined;

    // Resolve the {PROJECT_FOLDER} reference to an actual File
    return FileSystem.fromReferenceString(refString, FileSystem.AudioFiles);
}

inline function getDisplayName()
{
    local f = getCurrentAudioFile();

    if (isDefined(f))
        return f.toString(1); // Filename without extension

    return "No file loaded";
}

// Navigate to sibling files in the same directory
inline function getNextFile(delta)
{
    local currentFile = getCurrentAudioFile();

    if (!isDefined(currentFile))
        return;

    local parentDir = currentFile.getParentDirectory();
    local siblings = FileSystem.findFiles(parentDir, "*.wav,*.aif", false);

    for (i = 0; i < siblings.length; i++)
    {
        if (siblings[i].isSameFileAs(currentFile))
        {
            local newIndex = Math.range(i + delta, 0, siblings.length - 1);
            player.setFile(siblings[newIndex].toString(0));
            return;
        }
    }
}
```

