name: drawAlignedTextShadow
params:
  - { name: text, type: String, desc: "The text whose shadow to render" }
  - { name: area, type: Array, desc: "Bounding rectangle `[x, y, w, h]` for text placement" }
  - { name: alignment, type: String, desc: "Text alignment within the area" }
  - { name: shadowData, type: var, desc: "Shadow configuration object" }
---
::

```javascript
g.drawAlignedTextShadow("Title", [10, 10, 200, 40], "left", {"Colour": 0x88000000, "Radius": 4, "Offset": [2, 2]});
```


Renders a blurred shadow behind text at the specified alignment. This method only draws the shadow, not the text itself. To display both, call `drawAlignedTextShadow` first, then `drawAlignedText` with the same text, area, and alignment.

The `shadowData` parameter is a JSON object with these properties:

| Property | Type | Default | Description |
|----------|------|---------|-------------|
| `Colour` | Colour | `0xFF000000` | Shadow colour |
| `Offset` | `[x, y]` | `[0, 0]` | Shadow offset in pixels |
| `Radius` | int | `0` | Blur radius in pixels (0 = no blur) |
| `Spread` | int | `0` | Shadow spread in pixels |
| `Inner` | bool | `false` | `true` for inner shadow, `false` for drop shadow |

#### Example

```javascript
const var Panel1 = Content.getComponent("Panel1");

Panel1.setPaintRoutine(function(g)
{
	g.setFontWithSpacing("Comic Sans MS", 40.0, 0.05);
	g.drawAlignedTextShadow("funky", this.getLocalBounds(0), "centred", { "Colour": Colours.red, "Offset": [0, 4], "Radius": 10});
	g.drawAlignedTextShadow("funky", this.getLocalBounds(0), "centred", { "Colour": Colours.green, "Offset": [2, 2], "Radius": 0});
	g.setColour(Colours.white);
	g.drawAlignedText("funky", this.getLocalBounds(0), "centred");
});
```

