name: drawInnerShadowFromPath
params:
  - { name: path, type: Object, desc: "A Path object defining the shape for the inner shadow" }
  - { name: area, type: Array, desc: "Bounding rectangle `[x, y, w, h]` to scale the path into" }
  - { name: colour, type: Colour, desc: "Shadow colour in 0xAARRGGBB format" }
  - { name: radius, type: double, desc: "Blur radius in pixels" }
  - { name: offset, type: Array, desc: "Shadow offset as `[x, y]` pixel values, controls light direction" }
---
::

```javascript
g.drawInnerShadowFromPath(myPath, [0, 0, 200, 200], 0x88000000, 6, [2, 2]);
```


Draws an inner shadow inside the outline of a Path object, creating an inset/recessed visual effect. Unlike `drawDropShadowFromPath` which renders the shadow extending outward, this method renders the shadow extending inward. The `offset` parameter shifts the apparent light direction - positive x shifts the shadow rightward (light from left), positive y shifts it downward (light from above).

If the path is empty or invalid, the method silently does nothing.

#### Drawinnershadowfrompath Modulation Arc

```javascript
// Context: drawInnerShadowFromPath adds depth to stroked paths by
// creating an inset shadow. For arcs, use createStrokedPath to convert
// the stroked outline into a filled path suitable for the shadow.

const var knobLaf = Content.createLocalLookAndFeel();

knobLaf.registerFunction("drawRotarySlider", function(g, obj)
{
    if (!obj.modulationActive) return;

    var arcPath = Content.createPath();
    arcPath.startNewSubPath(0.0, 0.0);
    arcPath.startNewSubPath(1.0, 1.0);
    var arcRange = 2.4;

    arcPath.addArc([0, 0, 1, 1],
        -arcRange + obj.modMinValue * 2.0 * arcRange,
        -arcRange + obj.modMaxValue * 2.0 * arcRange);

    var arcArea = [6, 6, obj.area[2] - 12, obj.area[3] - 12];
    var strokeStyle = {"Thickness": 3};

    // Draw the modulation arc
    g.setColour(Colours.withAlpha(obj.itemColour1, 0.6));
    g.drawPath(arcPath, arcArea, strokeStyle);

    // Convert stroked path to filled shape for inner shadow
    var strokedPath = arcPath.createStrokedPath(strokeStyle, "");
    g.drawInnerShadowFromPath(
        strokedPath, arcArea,
        Colours.withAlpha(obj.itemColour1, obj.clicked ? 1.0 : 0.5),
        3, [0, 0]
    );
});
```

