name: drawLine
params:
  - { name: x1, type: double, desc: "Start x-coordinate of the line" }
  - { name: x2, type: double, desc: "End x-coordinate of the line" }
  - { name: y1, type: double, desc: "Start y-coordinate of the line" }
  - { name: y2, type: double, desc: "End y-coordinate of the line" }
  - { name: lineThickness, type: double, desc: "Stroke width in pixels" }
---
::

```javascript
g.drawLine(10.0, 190.0, 20.0, 80.0, 2.0);
```


Draws a straight line from point (x1, y1) to point (x2, y2) with the specified stroke thickness, using the current colour.

::warning{title="Parameter order is x1, x2, y1, y2"}
The parameter order is `(x1, x2, y1, y2, thickness)`, grouping x-coordinates before y-coordinates. This is unusual - most drawing APIs use point-by-point order `(x1, y1, x2, y2)`. Despite the unusual order, the line draws correctly from (x1, y1) to (x2, y2).
::

#### Drawline Grid Lines

```javascript
// Context: drawLine groups x-coordinates then y-coordinates:
// (x1, x2, y1, y2, thickness). This example draws horizontal and
// vertical reference lines for a display panel.

const var displayPanel = Content.addPanel("displayPanel", 0, 0);
displayPanel.set("width", 200);
displayPanel.set("height", 100);

displayPanel.setPaintRoutine(function(g)
{
    g.fillAll(0xFF222222);

    g.setColour(0x33FFFFFF);

    // Horizontal centre line: from x=0 to x=width, at y=50
    // Parameter order: x1, x2, y1, y2, thickness
    g.drawLine(0.0, this.getWidth(), 50, 50, 1.0);

    // Vertical centre line: from x=100 to x=100 (same x), y=0 to y=height
    g.drawLine(100.0, 100.0, 0.0, this.getHeight(), 1.0);
});
```

