name: drawPath
params:
  - { name: path, type: Object, desc: "A Path object defining the shape to stroke" }
  - { name: area, type: Array, desc: "Optional bounding rectangle `[x, y, w, h]` to scale the path into" }
  - { name: strokeStyle, type: var, desc: "Stroke thickness (number) or stroke configuration (JSON)" }
---
::

```javascript
g.drawPath(myPath, [0, 0, 200, 100], 2.0);
```


Draws the outline (stroke) of a Path object using the current colour. If `area` is an `[x, y, w, h]` array, the path is scaled to fit the rectangle. If `area` is omitted or not an array, the path is drawn at its original coordinates.

The `strokeStyle` parameter accepts two formats:

1. **Number** - simple stroke thickness (e.g., `2.0`)
2. **JSON object** - advanced stroke configuration:

| Property | Type | Description |
|----------|------|-------------|
| `Thickness` | float | Stroke width in pixels |
| `EndCapStyle` | String | `"butt"`, `"square"`, or `"rounded"` |
| `JointStyle` | String | `"mitered"`, `"curved"`, or `"beveled"` |

#### Example

```javascript
const var c = Content.createPath();

c.startNewSubPath(0.0, 0.0);
c.lineTo(0.0, 1.0);
c.lineTo(1.0, 0.0);
c.lineTo(0.5, 1.0);

const var Panel1 = Content.getComponent("Panel1");

Panel1.setPaintRoutine(function(g)
{
    g.fillAll(0x22FFFFFF);
    g.setColour(Colours.white);

    var p = {};               // Pick one of these:
    p.EndCapStyle = "butt";   // ["butt", "square", "rounded"]
    p.JointStyle = "rounded"; // ["mitered", "curved","beveled"]
    p.Thickness = 12.0;

	g.drawPath(c, this.getLocalBounds(p.Thickness), p);
});
```

