name: fillRoundedRectangle
params:
  - { name: area, type: Array, desc: "Bounding rectangle `[x, y, w, h]`" }
  - { name: cornerData, type: var, desc: "Corner radius (number) or per-corner config (JSON)" }
---
::

```javascript
g.fillRoundedRectangle([10, 10, 100, 50], 5.0);
```


Fills a rounded rectangle using the current colour. The `cornerData` parameter accepts a number for uniform corner radius, or a JSON object for per-corner control:

| Property | Type | Description |
|----------|------|-------------|
| `CornerSize` | float | Radius for rounded corners in pixels |
| `Rounded` | Array | `[topLeft, topRight, bottomLeft, bottomRight]` booleans controlling which corners are rounded |

When all four `Rounded` values are `false`, a plain rectangle is filled instead. To draw only the outline, use `drawRoundedRectangle`.

The area accepts an `[x, y, width, height]` array or a `Rectangle` object. `Rectangle` is recommended for LAF button backgrounds and panel styling:

```javascript
laf.registerFunction("drawToggleButton", function(g, obj)
{
    var rect = Rectangle(obj.area);
    g.setColour(obj.value ? 0xFF4466CC : 0xFF333333);
    g.fillRoundedRectangle(rect.reduced(1), 4.0);

    g.setColour(0xFFFFFFFF);
    g.setFont("Arial", 13.0);
    g.drawAlignedText(obj.text, rect, "centred");
});
```

#### Fillroundedrectangle Percorner Button

```javascript
// Context: Buttons at the edges of a tab bar need rounded corners on one
// side only. The JSON cornerData format controls which corners are rounded.

const var tabBarLaf = Content.createLocalLookAndFeel();

tabBarLaf.registerFunction("drawToggleButton", function(g, obj)
{
    var isFirst = obj.text == "MAIN";
    var isLast = obj.text == "SETTINGS";

    // Rounded corners only on the outer edges of the tab bar
    var roundData = {
        "CornerSize": 4,
        "Rounded": [isFirst, isLast, isFirst, isLast]
    };

    g.setColour(obj.value ? 0xFFCCCCCC : 0xFF313234);
    g.fillRoundedRectangle(obj.area, roundData);

    g.setColour(obj.value ? 0xFF222222 : 0xFF999999);
    g.setFontWithSpacing("medium", 12.0, 0.03);
    g.drawAlignedText(obj.text, obj.area, "centred");
});
```

