name: setFontWithSpacing
params:
  - { name: fontName, type: String, desc: "Name of the font to use" }
  - { name: fontSize, type: double, desc: "Font height in pixels" }
  - { name: spacing, type: double, desc: "Extra kerning factor added between characters" }
---
