::method-heading{name="getControllerNumber"}
::

```javascript
var cc = Message.getControllerNumber();
```

Returns the controller number of the current event inside `onController`. For standard CCs this is the actual CC number (0-127). Pitch bend and aftertouch also route through `onController` and return virtual CC numbers: 128 (`Message.PITCH_BEND_CC`) for pitch bend, 129 (`Message.AFTERTOUC_CC`) for aftertouch. This lets you handle all three event types uniformly with a single switch or if-chain.

::warning{title="CC range filter excludes pitch and aftertouch"}
Code that filters by CC range (e.g. `if (cc < 128)`) will implicitly exclude pitch wheel and aftertouch events.
::

#### Unified Controller Routing

```javascript
// Context: The onController callback receives CC, pitch bend, aftertouch,
// and program change events. Use getControllerNumber() with the virtual
// CC constants to handle them uniformly.

function onController()
{
    local cc = Message.getControllerNumber();
    local val = Message.getControllerValue();

    if (cc == 64)
    {
        // Sustain pedal
        local pedalDown = val > 64;
        // ... handle sustain logic
    }
    else if (cc == 1)
    {
        // Mod wheel -> vibrato depth
        Synth.getModulator("Vibrato").setIntensity(val / 127.0);
    }
    else if (cc == Message.PITCH_BEND_CC) // 128
    {
        // Pitch wheel: val is 0-16383 (14-bit), not 0-127
        local normalized = (val - 8192) / 8192.0; // -1.0 to +1.0
        // ... apply pitch bend
    }
    else if (cc == Message.AFTERTOUC_CC) // 129
    {
        // Channel aftertouch: val is 0-127
        // ... apply aftertouch modulation
    }
    else if (Message.isProgramChange())
    {
        // Program change events also route through onController
        local pgm = Message.getProgramChangeNumber();
        // ... switch preset
    }
}
```

