name: setStartOffset
params:
  - { name: newStartOffset, type: double, desc: "Number of samples to skip at voice start" }
---
::

```javascript
Message.setStartOffset(4410);
```


Sets the sample start offset on the current event. The sound generator skips ahead by this many samples when the voice starts, which is useful for starting playback at a specific position within a sample or wavetable cycle. The maximum offset is 65535 samples (approximately 1.36 seconds at 48kHz).

::warning{title="Controls playback position, not timing"}
Start offset controls where playback begins within the sample. It does not delay when the event is processed - use `Message.delayEvent()` for timing delays.
::

#### Per Note Phase Offset

```javascript
// Context: An additive synthesis instrument uses setStartOffset to start
// each harmonic oscillator at a different phase position per note,
// creating organic key-click and attack variation. The phase angle
// is converted from radians to a sample offset within a single
// wavetable cycle.

const var CYCLE_LENGTH = 2048; // Samples per wavetable cycle

// Pre-computed phase offsets per MIDI note (radians)
const var phaseTable = [];

for (i = 0; i < 128; i++)
    phaseTable.push(Math.sin(i * 1.7) * Math.PI); // Pseudo-random distribution

function onNoteOn()
{
    local note = Message.getNoteNumber();

    // Convert phase angle (radians) to sample offset within one cycle
    local phaseDeg = Math.toDegrees(phaseTable[note] + (2 * Math.PI));
    local offset = parseInt(phaseDeg / 360 * CYCLE_LENGTH);

    Message.setStartOffset(offset);
}
```

