name: ignoreEvent
params:
  - { name: shouldBeIgnored, type: int, desc: "Whether to mark the event as ignored (true/1) or clear the flag (false/0)" }
---
::

```javascript
mh.ignoreEvent(true);
```


Sets or clears the ignored flag on the stored event. When an event is marked as ignored, it remains in the MIDI buffer but is skipped during processing. This is useful when preparing events for re-injection that should arrive pre-flagged.

::warning{title="Only modifies stored copy, not live event"}
This modifies only the stored copy's flag, not the live event in the audio buffer. To suppress the original event during a MIDI callback, call `Message.ignoreEvent(true)` on the `Message` object, not on the MessageHolder.
::

#### Release Sample Store Ignore Reinject (skipped)

```javascript
// Context: A sampler that intercepts NoteOn events, stores them for later,
// and re-injects modified copies when the key is released. The hold duration
// determines which sample group to trigger.

const var holder = Engine.createMessageHolder();
const var uptimes = [];
uptimes.reserve(128);

for (i = 0; i < 128; i++)
    uptimes[i] = 0.0;

// Called from onNoteOn callback
inline function handleNoteOn()
{
    Message.store(holder);
    uptimes[Message.getNoteNumber()] = Engine.getUptime();

    // Suppress the original NoteOn - we'll trigger our own later
    Message.ignoreEvent(true);
}

// Called from onNoteOff callback
inline function handleNoteOff()
{
    // Store the NoteOff into the same holder (captures note number for matching)
    Message.store(holder);

    local duration = Engine.getUptime() - uptimes[holder.getNoteNumber()];
    local useShortRelease = duration < 0.8;

    // Select sample group based on how long the note was held
    Sampler.setActiveGroup(useShortRelease ? 1 : 2);
    holder.setGain(-6);

    Synth.addMessageFromHolder(holder);
}
```

