::method-heading
---
name: saveAsMidiFile
params:
  - { name: file, type: String, desc: "File path or reference string for the output MIDI file." }
  - { name: trackIndex, type: int, desc: "Track index in the output MIDI file (zero-based)." }
---
::

```javascript
mp.saveAsMidiFile("{PROJECT_FOLDER}output.mid", 0);
```


Saves the current sequence to a MIDI file at the given path, writing data to the specified track index. The MIDI file pool is reloaded automatically after saving, so the file is immediately available via `getMidiFileList()`. Returns true on success.

::warning{title="Overwrites target file permanently"}
This operation is not undoable and permanently overwrites the target file. The original content cannot be recovered unless you have a separate backup.
::

#### Edit And Save Midi Workflow

```javascript
// Context: Load a MIDI file, process the events (remap notes, adjust
// velocities), then save back to a new location

const var mp = Synth.getMidiPlayer("MidiPlayer1");

inline function processAndSave(inputFile, outputFile, trackIndex)
{
    mp.setFile(inputFile, true, true);
    mp.setTrack(trackIndex);

    local events = mp.getEventList();

    // Remap note numbers using a conversion table
    for (e in events)
    {
        local nn = e.getNoteNumber();

        if (e.isNoteOn())
            e.setVelocity(Math.min(127, parseInt(e.getVelocity() * 1.1)));

        e.setNoteNumber(nn + 12);
    }

    mp.flushMessageList(events);
    mp.saveAsMidiFile(outputFile, trackIndex - 1); // track index is zero-based here
}
```

