name: setRecordEventCallback
params:
  - { name: recordEventCallback, type: Function, desc: "Inline function with one MessageHolder parameter." }
---
::

```javascript
mp.setRecordEventCallback(onRecordEvent);
```


Registers an inline function that processes every MIDI event about to be recorded. The callback receives a single MessageHolder argument and can modify or filter events before they are written to the sequence - for example, quantising timestamps to a grid or ignoring notes outside a target range.

::warning{title="Runs on audio thread, use inline function"}
This callback runs on the audio thread and must be an inline function. Regular functions will throw a script error. Avoid any operations that allocate memory or block.
::

#### Quantize And Filter Recording

```javascript
// Context: A record event callback that filters out notes not matching the
// current channel and quantizes timestamps to the grid. This runs on the
// audio thread so it must be an inline function.

const var mp = Synth.getMidiPlayer("MidiPlayer1");
mp.setUseTimestampInTicks(true);

const var CHANNEL_NOTE = 36; // The note number this channel responds to

inline function onRecordEvent(e)
{
    if (e.isNoteOn())
    {
        local number = e.getNoteNumber();

        // Filter out notes that don't belong to this channel
        if (number != CHANNEL_NOTE)
        {
            e.ignoreEvent(true);
            return;
        }

        // Quantize to 16th note grid
        local tpq = mp.getTicksPerQuarter(); // 960
        local gridSize = tpq / 4;            // 240 ticks = 16th note
        local ts = e.getTimestamp();
        local quantised = Math.round(ts / gridSize) * gridSize;
        e.setTimestamp(quantised);
    }
}

mp.setRecordEventCallback(onRecordEvent);
```

