name: set
params:
  - { name: propertyName, type: String, desc: "The property identifier to set" }
  - { name: value, type: var, desc: "The new value for the property" }
---
::

```javascript
cb.set("text", "Select...");
```


Sets a component property to the given value. During `onInit`, changes are applied without UI notification; outside `onInit`, the UI updates automatically.

| Property | Description |
|----------|-------------|
| `x`, `y`, `width`, `height` | Position and size in pixels, relative to parent |
| `visible`, `enabled`, `locked` | Display and interaction state |
| `text`, `tooltip` | Display text (shown when nothing is selected) and hover tooltip |
| *`items`* | Newline-separated list of selectable items; setting this auto-updates the value range |
| *`fontName`*, *`fontSize`*, *`fontStyle`* | Font family, size, and style for the displayed text |
| `bgColour`, `itemColour`, `itemColour2`, `textColour` | Colour properties |
| `parentComponent` | Parent component for layout nesting |
| `defaultValue` | Default value (1-based item index); `min`/`max` are auto-managed and not settable |
| `saveInPreset`, `useUndoManager`, `deferControlCallback` | Preset persistence, undo, and callback deferral |
| `isPluginParameter`, `pluginParameterName`, `pluginParameterGroup`, `automationID`, *`enableMidiLearn`* | DAW automation and MIDI learn |
| `macroControl`, `isMetaParameter`, `linkedTo` | Macro control and parameter linking |
| `processorId`, `parameterId` | Module parameter connection |
| *`popupAlignment`*, *`useCustomPopup`* | Popup menu position (`bottom`, `top`, `topRight`, `bottomRight`) and custom submenu/header/separator parsing |

#### Custom Popup Sections (validated)

```javascript
// Context: When useCustomPopup is enabled, the items string supports special
// formatting syntax for organizing complex option lists into sections.

const var cb = Content.addComboBox("FxSelector", 0, 0);
cb.set("useCustomPopup", true);
cb.set("saveInPreset", false);

// Headers (**...**) and separators (___) do not consume selection indices.
// Submenu syntax (Category::Item) creates nested popup menus.
// The value index counts only selectable items.
cb.set("items", [
    "**Filters**",
    "Filters::LowPass",
    "Filters::HighPass",
    "Filters::BandPass",
    "___",
    "**Dynamics**",
    "Dynamics::Compressor",
    "Dynamics::Gate",
    "___",
    "**Spatial**",
    "Spatial::Chorus",
    "Spatial::Delay",
    "Spatial::Reverb"
].join("\n"));

// Value 1 = "LowPass" (first selectable item, not the header)
// Value 4 = "Compressor" (headers and separators are skipped)
cb.setValue(1);
Console.print(cb.getItemText()); // "LowPass" -- submenu prefix stripped
```

#### Factory Pattern Namespace (validated)

```javascript
// Context: Create and configure combo boxes inside a namespace function that returns
// the configured component. This pattern keeps creation, styling, and callback
// assignment together for reusable selector components.

namespace Selectors
{
    inline function onSelectorChanged(component, value)
    {
        Console.print(component.getId() + ": " + parseInt(value));
    }

    inline function makeSelector(name, items, x, y)
    {
        local cb = Content.addComboBox(name, x, y);
        cb.set("width", 120);
        cb.set("height", 28);
        cb.set("items", items.join("\n"));
        cb.set("text", "Select...");
        cb.set("saveInPreset", false);
        cb.setControlCallback(onSelectorChanged);
        return cb;
    }
}

const var cbWaveform = Selectors.makeSelector("Waveform", ["Sine", "Saw", "Square"], 0, 0);
const var cbFilter = Selectors.makeSelector("FilterType", ["LP", "HP", "BP"], 140, 0);
```

