params:
  - { name: subURL, type: String, desc: "Path segment appended to the base URL" }
  - { name: parameters, type: ComplexType, desc: "Request parameters: flat JSON object for query params, nested JSON for JSON body, or string for raw data" }
  - { name: callback, type: Function, desc: "Callback invoked when response arrives" }
---
