name: attachNote
params:
  - { name: originalNoteId, type: int, desc: "Event ID of the original (real) note to attach to" }
  - { name: artificialNoteId, type: int, desc: "Event ID of the artificial note to be auto-stopped" }
---
::

```javascript
var ok = Synth.attachNote(Message.getEventId(), artificialId);
```


Links an artificial note to an original note so that when the original receives a note-off, the artificial note is automatically stopped as well. This eliminates the need for manual note-off tracking in `onNoteOff` when layering artificial notes on top of incoming events. Returns `true` if the attachment succeeded.

::warning{title="Requires setFixNoteOnAfterNoteOff first"}
Requires `Synth.setFixNoteOnAfterNoteOff(true)` to be called first, typically in `onInit`. Without it, a script error is thrown.
::

#### Auto Release Octave Layer

```javascript
// Context: A synth generates an artificial note one octave above each incoming note.
// attachNote links the artificial to the original so that releasing the key
// automatically stops both, eliminating manual note-off tracking in onNoteOff.

// Required: enable the attached note buffer before using attachNote
Synth.setFixNoteOnAfterNoteOff(true);

inline function onNoteOn()
{
    local originalId = Message.getEventId();

    // Generate an artificial note one octave up
    local octaveId = Synth.addNoteOn(1, Message.getNoteNumber() + 12, Message.getVelocity(), 0);

    // Link: when the original note-off arrives, the octave note is auto-killed
    Synth.attachNote(originalId, octaveId);
}

// No onNoteOff handling needed -- the attached note is released automatically
```

