name: setAutomationValue
params:
  - { name: automationIndex, type: int, desc: "The zero-based index of the custom automation slot. Use `getAutomationIndex` to convert from string ID." }
  - { name: newValue, type: double, desc: "The new value for the automation slot. Clamped to the slot's configured range." }
---
::

```javascript
uph.setAutomationValue(0, 0.75);
```


Sets the value of a custom automation slot by its zero-based index. The value is clamped to the slot's configured range, snapped to its step size, and dispatched synchronously through all connections (module parameters, meta-connections, cable connections). Use `getAutomationIndex` to convert a string ID to the index. For proper DAW automation recording, bracket value changes with `sendParameterGesture` begin/end pairs.

::warning{title="Returns false silently on failure"}
Returns false silently if the custom data model is not active or the index is out of range. No error is thrown, so check the return value to detect failure.
::

#### Xy Pad Automation

```javascript
// Context: A ScriptPanel acting as an XY pad uses setAutomationValue
// to push its position into the automation system. This routes the
// values through all connections (processor parameters, cables, meta
// connections) and notifies any attached callbacks.

const var uph = Engine.createUserPresetHandler();

// Cache automation indices at init time for performance.
// These IDs must match slots registered via setCustomAutomation.
const var xIndex = uph.getAutomationIndex("Mixer 1 X");
const var yIndex = uph.getAutomationIndex("Mixer 1 Y");

inline function onPadChange(component, value)
{
    // value is a 2-element array [x, y] from the XY pad
    uph.setAutomationValue(xIndex, value[0]);
    uph.setAutomationValue(yIndex, value[1]);
}

// Reset to center position
inline function resetPad()
{
    uph.setAutomationValue(xIndex, 0.5);
    uph.setAutomationValue(yIndex, 0.0);
}
```

