name: concat
params:
  - { name: arrayToConcat, type: Array, desc: "Array whose elements will be appended" }
---
::

```javascript
a.concat([4, 5, 6]);
```


Appends all elements from the given array (or arrays) to this array. Modifies the array in-place and returns `undefined`. Accepts multiple array arguments. Non-array arguments are silently ignored - use `push()` to append individual values.

::warning{title="Modifies in-place, unlike JavaScript"}
Unlike `Array.prototype.concat` in JavaScript, this method modifies the array in-place and returns `undefined`. Writing `var b = a.concat([4, 5])` assigns `undefined` to `b`.
::

#### Build Master Param List (validated)

```javascript
// Context: A plugin with multiple channel strips builds its full
// automation parameter list by creating sub-arrays per channel,
// then concatenating them into one master array. concat() modifies
// in-place -- there is no return value.

inline function makeChannelParams(channelIndex)
{
    local params = [];
    local ch = channelIndex + 1;

    params.push({
        "ID": "Volume " + ch,
        "min": -100.0,
        "max": 0.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Gain" }]
    });

    params.push({
        "ID": "Pan " + ch,
        "min": -100.0,
        "max": 100.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Balance" }]
    });

    return params;
}

// Accumulate all channel parameters into one list
const var NUM_CHANNELS = 4;
const var allParams = [];

for(i = 0; i < NUM_CHANNELS; i++)
    allParams.concat(makeChannelParams(i));

Console.print(allParams.length); // 8 (2 params x 4 channels)
```

