::method-heading
---
name: addStaticGlobalModulator
params:
  - { name: chainIndex, type: int, desc: "Modulator chain index (1 = Gain, 2 = Pitch)" }
  - { name: timeVariantMod, type: Object, desc: "Reference to a time-variant modulator in a GlobalModulatorContainer" }
  - { name: modName, type: String, desc: "Name for the new static modulator receiver" }
---
::

```javascript
var mod = cs.addStaticGlobalModulator(1, globalLfo, "StaticGainLFO");
```


Adds a static global modulator receiver to the specified modulator chain. Unlike `addGlobalModulator`, a static receiver provides a single modulation value per audio block rather than per voice. This is more efficient when voice independence is not needed - typical targets include effect parameters, FM depth, or synth-level controls. The `timeVariantMod` must be a reference to a modulator inside a GlobalModulatorContainer. Returns the new modulator as a Modulator handle, or undefined if creation fails.

::warning{title="Default to static unless per-voice needed"}
Some modulation targets only operate at block level. Using `addGlobalModulator` on these targets wastes CPU computing per-voice values that collapse to a single value. Default to `addStaticGlobalModulator` unless per-voice independence is specifically required (e.g. per-voice tremolo or vibrato).
::

#### Static Vs Pervoice Choice

```javascript
// Context: A modulation matrix decides at connection time whether to use
// per-voice (addGlobalModulator) or static (addStaticGlobalModulator)
// modulation based on the target type. Effect parameters and synth-level
// controls don't need per-voice resolution.

const var globalLFO = Synth.getModulator("GlobalLFO1");
const var globalCC = Synth.getModulator("GlobalCC");

const var oscGroup = Synth.getChildSynth("Oscillator1");

const var GAIN_CHAIN = 1;
const var PITCH_CHAIN = 2;

inline function addModConnection(source, target, chainIndex, name, useStatic)
{
    local newMod;

    if (useStatic)
    {
        // Static: one value per audio block, shared across all voices.
        // More CPU-efficient for targets like effect parameters, FM depth,
        // or any control that doesn't need per-voice independence.
        newMod = target.addStaticGlobalModulator(chainIndex, source, name);
    }
    else
    {
        // Per-voice: each voice gets its own modulation value.
        // Required for gain/pitch chains where voice independence matters
        // (e.g., per-voice tremolo or vibrato).
        newMod = target.addGlobalModulator(chainIndex, source, name);
    }

    if (isDefined(newMod))
        newMod.setIntensity(1.0);

    return newMod;
}

// CC modulation on gain chain: static is sufficient (no per-voice needed)
addModConnection(globalCC, oscGroup, GAIN_CHAIN, "CC_Vol", true);

// LFO on pitch chain: per-voice for independent vibrato per voice
addModConnection(globalLFO, oscGroup, PITCH_CHAIN, "LFO_Pitch", false);
```

