::method-heading
---
name: getWildcardReference
params:
  - { name: relativePath, type: String, desc: "Relative path within the expansion" }
---
::

```javascript
var ref = e.getWildcardReference("SampleMaps/Piano.xml");
```


Constructs a wildcard reference string in the format `{EXP::ExpansionName}relativePath` by prepending this expansion's wildcard prefix to the given path. The resulting string can be used with any pool-based API to address expansion-specific resources - for example, setting an image on a UI component or loading a sample map.

::warning{title="No file existence check"}
The method performs string concatenation only. It does not verify that the referenced file exists. A wrong relative path produces a valid-looking reference that silently fails to load.
::

#### Expansion Image Swap

```javascript
// Context: Swap background and panel images when the active expansion
// changes. Fall back to project folder images when no expansion is active.

const var BackgroundImage = Content.getComponent("BackgroundImage");
const var expHandler = Engine.createExpansionHandler();

inline function onExpansionChanged(newExpansion)
{
    local bgRef = "";

    if (isDefined(newExpansion))
    {
        // Build a wildcard reference: {EXP::ExpansionName}background.png
        bgRef = newExpansion.getWildcardReference("background.png");
    }
    else
    {
        // No expansion active -- use the project's own image
        bgRef = "{PROJECT_FOLDER}background.png";
    }

    BackgroundImage.set("fileName", bgRef);
}

expHandler.setExpansionCallback(onExpansionChanged);

// Initialise with no expansion
onExpansionChanged(undefined);
```

