name: setCurrentExpansion
params:
  - { name: expansionName, type: String, desc: "Expansion name or Expansion reference" }
---
::

```javascript
var ok = eh.setCurrentExpansion("MyExpansion");
```


Sets the currently active expansion by name (or by `Expansion` object reference) and triggers the expansion callback. Pass an empty string to clear the current expansion - the callback receives `undefined`.

While only one expansion can be "active" at a time, this does not mean you cannot load content from multiple expansions simultaneously. You do not need to call `setCurrentExpansion()` before loading data from an expansion. The active expansion is primarily a UI convenience - it allows you to adapt the interface to whichever expansion was most recently selected.

When the first expansion is activated (transitioning from no active expansion), the handler saves the current default state for later restoration.

#### Combobox Expansion Switching

```javascript
// Context: Wire a ComboBox to switch the active expansion. The first item
// ("No Expansion") maps to an empty string which clears the selection.

const var eh = Engine.createExpansionHandler();

const var expansionNames = ["No Expansion"];

for (e in eh.getExpansionList())
    expansionNames.push(e.getProperties().Name);

const var ExpansionSelector = Content.getComponent("ExpansionSelector");
ExpansionSelector.set("items", expansionNames.join("\n"));

inline function onExpansionSelectorControl(component, value)
{
    local name = component.getItemText();

    // First item clears the expansion - pass empty string
    if (name == expansionNames[0])
        name = "";

    eh.setCurrentExpansion(name);
};

ExpansionSelector.setControlCallback(onExpansionSelectorControl);
```

#### Close Button Deactivation

```javascript
// Context: When a plugin loads as an expansion inside a shell product,
// provide a close button to return to the base product state.

const var eh = Engine.createExpansionHandler();

const var closeButton = Content.getComponent("CloseButton");
closeButton.set("allowCallbacks", "Clicks & Hover");

closeButton.setMouseCallback(function(event)
{
    this.data.hover = event.hover;
    this.repaint();

    if (event.clicked)
        eh.setCurrentExpansion("");
});
```

