```javascript
const var eh = Engine.createExpansionHandler();

inline function onExpansionError(message, isCritical)
{
    if (isCritical)
        Console.print("CRITICAL: " + message);
    else
        Console.print("Info: " + message);
};

eh.setErrorFunction(onExpansionError);
```

