const var a = f.createArray(4);

a[0].id = 3;
a[1].id = 1;
a[2].id = 4;
a[3].id = 2;

f.setCompareFunction("id");
a.sort();

Console.print(a[0].id); // 1
Console.print(a[3].id); // 4
