name: skew
params:
  - { name: start, type: double, desc: "The range start value" }
  - { name: end, type: double, desc: "The range end value" }
  - { name: midPoint, type: double, desc: "The value that should map to 0.5 normalised" }
---
::

```javascript
var s = Math.skew(20.0, 20000.0, 1000.0);
```


Returns the skew factor for a range where the given mid-point maps to 0.5 in normalised space. The returned value can be used as the `SkewFactor` property in range objects passed to `Math.from0To1()` and `Math.to0To1()`.

The most practical use is converting UI component ranges (which use `middlePosition`) to skew-factor-based ranges for better performance. The `middlePosition` convention requires an extra logarithm calculation on every conversion call; pre-computing the skew factor with `Math.skew()` eliminates that overhead. Combined with a fix object, this can reduce `from0To1` conversion time from around 83 ms to 25 ms per 100,000 calls:

```javascript
// Convert a middlePosition range to a skewFactor range
var skewRange = {
    "MinValue": 20.0,
    "MaxValue": 20000.0,
    "SkewFactor": Math.skew(20.0, 20000.0, 1000.0)
};

// Wrap in a fix object for maximum performance
const var factory = Engine.createFixObjectFactory(skewRange);
const var range = factory.create();
var value = Math.from0To1(0.5, range);
```

#### Example

```javascript
// This is a range how it would come from a UI component
// it defines the curve with a middle position
const var p1 = {
	min: 20.0,
	max: 20000.0,
	middlePosition: 1000.0
}

// Using a skew-based range avoids an additional log calculation
// in the conversion functions
const var p2 = {
	MinValue: p1.min,
	MaxValue: p1.max,
	SkewFactor: Math.skew(p1.min, p1.max, p1.middlePosition)
};

// We're caring about performance here so we use fix objects:
const var f1 = Engine.createFixObjectFactory(p1);
const var f2 = Engine.createFixObjectFactory(p2);
const var o1 = f1.create();
const var o2 = f2.create();

{
	.profile(" - mid point with JSON");

	for(i = 0; i < 100000; i++)
		Math.from0To1(0.5, p1);
}

{
	.profile(" - skew factor with JSON");

	for(i = 0; i < 100000; i++)
		Math.from0To1(0.5, p2);
}

{
	.profile(" - mid point with fix object");

	for(i = 0; i < 100000; i++)
		Math.from0To1(0.5, o1);
}

{
	.profile(" - skew factor with fix object");

	for(i = 0; i < 100000; i++)
		Math.from0To1(0.5, o2);
}

/* Results:
- mid point with JSON: 83.185 ms
- skew factor with JSON: 29.896 ms
- mid point with fix object: 27.032 ms
- skew factor with fix object: 24.955 ms
*/
```

