name: purgeMicPosition
params:
  - { name: micName, type: String, desc: "Mic position name (channel suffix)" }
  - { name: shouldBePurged, type: int, desc: "true to purge, false to unpurge" }
---
::

```javascript
sampler.purgeMicPosition("Close", true);
```


Purges or unpurges a mic position channel by name. The name must match the channel suffix exactly - use `Sampler.getMicPositionName()` to get valid names. Only works with multi-mic samplers.

::warning{title="Call on each sampler individually"}
When managing mic positions across multiple samplers, you must call this on each sampler individually. There is no global purge API.
::

#### Multi Sampler Mic Purge

```javascript
// Context: A multi-mic instrument purges/unpurges mic positions across all samplers
// based on a mode matrix (e.g., Classic uses all mics, Pop uses only Mid).

const var NUM_MICS = 3;

const var samplers = [Synth.getSampler("Sustain"),
                      Synth.getSampler("Release"),
                      Synth.getSampler("Pedal")];

const var micGains = [Synth.getEffect("Close"),
                      Synth.getEffect("Mid"),
                      Synth.getEffect("Far")];

const var micNames = ["Close", "Mid", "Far"];

// Mode matrix: 1 = user-controlled, 0 = forced off, 2 = forced on
//                CLOSE  MID  FAR
const var MATRIX = [[1,    1,   1],   // Classic
                    [0,    2,   0],   // Pop
                    [0,    2,   2]];  // Cinematic

reg currentMode = 0;

inline function purgeMic(micIndex, shouldBeEnabled)
{
    // Purge the mic position across ALL samplers simultaneously
    for (s in samplers)
        s.purgeMicPosition(micNames[micIndex], !shouldBeEnabled);
}

inline function refreshAllMics()
{
    for (i = 0; i < NUM_MICS; i++)
    {
        local modeValue = MATRIX[currentMode][i];

        // 2 = forced on regardless of button, 0 = forced off, 1 = user choice
        if (modeValue == 2)
            purgeMic(i, true);
        else if (modeValue == 0)
            purgeMic(i, false);
        else
            purgeMic(i, micButtons[i].getValue());
    }
}
```

